-- Socle 1.6.0 : référentiel des activités (eqNAF), commun à tous les projets du Studio.
-- Source de vérité : table eqnaf de la base SCM (décision D-ESH-2026-10-06-01) ; ce bloc en est la
-- copie au 07/10/2026 (164 entrées, empreinte identique). Une mise à jour du registre = une version du socle.
-- 1. Table : lecture publique des activités actives, écriture réservée à l'administrateur.
CREATE TABLE IF NOT EXISTS public.activites (
  code text PRIMARY KEY,
  libelle text NOT NULL,
  type text NOT NULL CHECK (type IN ('professionnel', 'non_professionnel')),
  categorie text NOT NULL,
  cadran text CHECK (cadran IN ('E', 'S')),
  code_naf_2025 text,
  statut text NOT NULL DEFAULT 'actif' CHECK (statut IN ('actif', 'inactif')),
  source text NOT NULL DEFAULT 'Registre eqNAF, base SCM',
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS activites_categorie_idx ON public.activites (categorie);
ALTER TABLE public.activites ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.activites FROM anon;
GRANT SELECT ON public.activites TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.activites TO authenticated;
GRANT ALL ON public.activites TO service_role;
DROP POLICY IF EXISTS activites_lecture ON public.activites;
CREATE POLICY activites_lecture ON public.activites FOR SELECT TO anon, authenticated USING (statut = 'actif');
DROP POLICY IF EXISTS activites_admin ON public.activites;
CREATE POLICY activites_admin ON public.activites FOR ALL TO authenticated
  USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
DROP TRIGGER IF EXISTS activites_updated_at ON public.activites;
CREATE TRIGGER activites_updated_at BEFORE UPDATE ON public.activites
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
-- 2. Registre.
ON CONFLICT (code) DO UPDATE SET libelle = excluded.libelle, type = excluded.type, categorie = excluded.categorie,
  cadran = excluded.cadran, statut = excluded.statut;
-- 3. Version.
VALUES ('1.6.0', 'brique', '2026-10-07',
  'Référentiel des activités (eqNAF) : secteurs professionnels et passions, communs à tous les projets.',
  'Table activites (164 entrées du registre eqNAF de la base SCM : 120 codes NAF du cadran S, 44 activités non professionnelles du cadran E, 29 catégories), lecture publique des activités actives, écriture réservée à l''admin.',
  '20261007220000_v1_6_0_activites')
ON CONFLICT (version) DO NOTHING;
VALUES ('socle', jsonb_build_object('version', '1.6.0', 'publie_le', '2026-10-07',
  'migration_reference', '20261007220000_v1_6_0_activites'))
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now()
WHERE string_to_array(coalesce(public.site_settings.value ->> 'version', '0.0.0'), '.')::int[]
      < string_to_array('1.6.0', '.')::int[];
